//! shape.zig — canonical /contract JSON shape validator.
//!
//! The substrate accepts pre-translated JSON envelopes (produced by
//! an outside LLM translator) and validates them against the schema
//! in `docs/contract-json-shape.md`. There are no CLI flags for
//! plan/action/parent — every verb reads JSON from stdin.
//!
//! Lewis 2026-05-26: "all /contract are just json generated by the
//! llm in the /contract shape from sentences — the llm just converts
//! to json of that shape, intentionally translating to the layer
//! below's terminology."
//!
//! This file is the boundary: anything that doesn't validate here
//! never lands in the ledger. The validator is pure (no I/O, no
//! signing) — callers run it, then either bail or hand the validated
//! shape to contract.declare/markSatisfied/etc to write the row.

const std = @import("std");
const pointer = @import("pointer.zig");

pub const ShapeError = error{
    NotAnObject,
    UnknownEvent,
    MissingId,
    BadIdShape,
    MissingPlan,
    MissingAction,
    UnknownActionPrefix,
    LayerOutOfRange,
    BadParentIdShape,
    BadSynapses,
    BadWave,
    BadJson,
    OutOfMemory,
};

pub const EventKind = enum {
    declared,
    iterated,
    satisfied,
    died,

    pub fn fromString(s: []const u8) ?EventKind {
        if (std.mem.eql(u8, s, "declared")) return .declared;
        if (std.mem.eql(u8, s, "iterated")) return .iterated;
        if (std.mem.eql(u8, s, "satisfied")) return .satisfied;
        if (std.mem.eql(u8, s, "died")) return .died;
        return null;
    }
};

/// Validated /contract shape. Slices borrow from the input bytes; the
/// caller must keep the input alive while reading these.
pub const Shape = struct {
    event: EventKind,
    id: ?[]const u8 = null,
    plan: ?[]const u8 = null,
    action: ?[]const u8 = null,
    layer: ?i32 = null,
    parent_id: ?[]const u8 = null,
    wave: ?u32 = null,
    proof: ?[]const u8 = null,
};

fn is8Hex(s: []const u8) bool {
    if (s.len != 8) return false;
    for (s) |c| {
        const ok = (c >= '0' and c <= '9') or (c >= 'a' and c <= 'f');
        if (!ok) return false;
    }
    return true;
}

/// Validate a JSON byte slice against the canonical shape. Returns
/// the parsed Shape on success; one of ShapeError on failure. Same
/// rule set as docs/contract-json-shape.md and the SDK validators —
/// drift between Zig and SDK validators is a substrate bug.
pub fn validateShape(
    allocator: std.mem.Allocator,
    json_bytes: []const u8,
) ShapeError!Shape {
    var parsed = std.json.parseFromSlice(
        std.json.Value,
        allocator,
        json_bytes,
        .{},
    ) catch return ShapeError.BadJson;
    defer parsed.deinit();
    const root = parsed.value;
    if (root != .object) return ShapeError.NotAnObject;
    const obj = root.object;

    // event
    const event_v = obj.get("event") orelse return ShapeError.UnknownEvent;
    if (event_v != .string) return ShapeError.UnknownEvent;
    const event = EventKind.fromString(event_v.string) orelse return ShapeError.UnknownEvent;

    var shape = Shape{ .event = event };

    // id — required for non-declared events; optional on declared
    if (obj.get("id")) |id_v| {
        if (id_v == .string) {
            if (!is8Hex(id_v.string)) return ShapeError.BadIdShape;
            shape.id = id_v.string;
        } else if (id_v != .null) {
            return ShapeError.BadIdShape;
        }
    } else if (event != .declared) {
        return ShapeError.MissingId;
    }

    // plan — required for declared / iterated
    if (event == .declared or event == .iterated) {
        const plan_v = obj.get("plan") orelse return ShapeError.MissingPlan;
        if (plan_v != .string) return ShapeError.MissingPlan;
        shape.plan = plan_v.string;
    }

    // action + layer — required for declared
    if (event == .declared) {
        const action_v = obj.get("action") orelse return ShapeError.MissingAction;
        if (action_v != .string or action_v.string.len == 0) return ShapeError.MissingAction;
        const action = action_v.string;
        if (!pointer.isKnownAction(action)) return ShapeError.UnknownActionPrefix;
        shape.action = action;

        const layer_v = obj.get("layer") orelse return ShapeError.LayerOutOfRange;
        if (layer_v != .integer) return ShapeError.LayerOutOfRange;
        const layer = layer_v.integer;
        if (layer < 0 or layer > 8) return ShapeError.LayerOutOfRange;
        shape.layer = @as(i32, @intCast(layer));
    }

    // parent_id — optional, 8-hex or null
    if (obj.get("parent_id")) |pv| {
        if (pv == .string) {
            if (!is8Hex(pv.string)) return ShapeError.BadParentIdShape;
            shape.parent_id = pv.string;
        } else if (pv != .null) {
            return ShapeError.BadParentIdShape;
        }
    }

    // synapses — optional list of {to:8hex, kind:string}
    if (obj.get("synapses")) |sv| {
        if (sv != .array) return ShapeError.BadSynapses;
        for (sv.array.items) |item| {
            if (item != .object) return ShapeError.BadSynapses;
            const to_v = item.object.get("to") orelse return ShapeError.BadSynapses;
            if (to_v != .string or !is8Hex(to_v.string)) return ShapeError.BadSynapses;
            const kind_v = item.object.get("kind") orelse return ShapeError.BadSynapses;
            if (kind_v != .string) return ShapeError.BadSynapses;
        }
    }

    // wave — optional on satisfied; must be int ≥ 1 when present
    if (obj.get("wave")) |wv| {
        if (wv != .integer or wv.integer < 1 or wv.integer > std.math.maxInt(u32)) {
            return ShapeError.BadWave;
        }
        shape.wave = @as(u32, @intCast(wv.integer));
    }

    // proof — optional string
    if (obj.get("proof")) |pf| {
        if (pf == .string) shape.proof = pf.string;
    }

    return shape;
}

// ─────────────────────────────────────────────────────────────────────
// Tests — Σ27 binding.

test "validates a canonical declared row" {
    const allocator = std.testing.allocator;
    const json =
        \\{"event":"declared","plan":"answer the user","action":"neuron:user","layer":3,"parent_id":"deadbeef"}
    ;
    const shape = try validateShape(allocator, json);
    try std.testing.expect(shape.event == .declared);
    try std.testing.expectEqualStrings("answer the user", shape.plan.?);
    try std.testing.expectEqualStrings("neuron:user", shape.action.?);
    try std.testing.expectEqual(@as(i32, 3), shape.layer.?);
    try std.testing.expectEqualStrings("deadbeef", shape.parent_id.?);
}

test "rejects unknown event" {
    const allocator = std.testing.allocator;
    const json =
        \\{"event":"celebrated","plan":"x","action":"neuron","layer":3}
    ;
    try std.testing.expectError(ShapeError.UnknownEvent, validateShape(allocator, json));
}

test "rejects layer out of 0..8" {
    const allocator = std.testing.allocator;
    const json =
        \\{"event":"declared","plan":"x","action":"neuron","layer":99}
    ;
    try std.testing.expectError(ShapeError.LayerOutOfRange, validateShape(allocator, json));
}

test "rejects unknown action prefix" {
    const allocator = std.testing.allocator;
    const json =
        \\{"event":"declared","plan":"x","action":"frobnicate:foo","layer":3}
    ;
    try std.testing.expectError(ShapeError.UnknownActionPrefix, validateShape(allocator, json));
}

test "rejects bad parent_id" {
    const allocator = std.testing.allocator;
    const json =
        \\{"event":"declared","plan":"x","action":"neuron","layer":3,"parent_id":"not-hex"}
    ;
    try std.testing.expectError(ShapeError.BadParentIdShape, validateShape(allocator, json));
}

test "satisfied requires 8-hex id and positive wave" {
    const allocator = std.testing.allocator;
    const good =
        \\{"event":"satisfied","id":"deadbeef","wave":1}
    ;
    _ = try validateShape(allocator, good);

    const bad_wave =
        \\{"event":"satisfied","id":"deadbeef","wave":0}
    ;
    try std.testing.expectError(ShapeError.BadWave, validateShape(allocator, bad_wave));

    const bad_id =
        \\{"event":"satisfied","id":"not-hex"}
    ;
    try std.testing.expectError(ShapeError.BadIdShape, validateShape(allocator, bad_id));
}

test "accepts boundary layers 0/7/8" {
    const allocator = std.testing.allocator;
    const word =
        \\{"event":"declared","plan":"x","action":"word:contract","layer":0}
    ;
    _ = try validateShape(allocator, word);
    const validate =
        \\{"event":"declared","plan":"x","action":"validate:deadbeef","layer":7}
    ;
    _ = try validateShape(allocator, validate);
    const signed =
        \\{"event":"declared","plan":"x","action":"signed:abc123","layer":8}
    ;
    _ = try validateShape(allocator, signed);
}

test "rejects bad synapses" {
    const allocator = std.testing.allocator;
    const json =
        \\{"event":"declared","plan":"x","action":"neuron","layer":3,"synapses":[{"to":"BADHEXX","kind":"pointer"}]}
    ;
    try std.testing.expectError(ShapeError.BadSynapses, validateShape(allocator, json));
}
